        return 0

    if len(set(items)) == 1:
        return items[0]

    has_neg = any(x < 0 for x in items)
    has_pos = any(x > 0 for x in items)
    has_zero = any(x == 0 for x in items)

    # Mixed signs
    if has_neg and has_pos:
        # Examples suggest duplicate-containing mixed lists collapse to 0,
        # while a unique mixed list returns the minimum value.
        if len(set(items)) != len(items):
            return 0
        return min(items)

    # All positive
    if has_pos and not has_neg and not has_zero:
        return min(items) if len(items) == 2 else max(items)

    # All non-positive
    return 0
